//! `fineprint-ingest vocab --cr <rules.txt> [--out <file>|-] [--check]`.
//!
//! - Default `--out` is [`DEFAULT_OUT`], resolved against the current directory (run from the
//!   repository root, as every documented command is).
//! - Without `--check`: writes the generated bytes to `--out` (or stdout for `-`) and prints one
//!   summary line (on stderr when the JSON goes to stdout).
//! - With `--check`: writes nothing, compares the generated bytes with the `--out` file and
//!   prints one summary line. A missing or different file is a violation; the message names the
//!   first differing top-level member and never quotes CR text.
//!
//! Exit codes (the xtask convention): 0 success, 1 violation (check mismatch or keyword id
//! collision), 2 usage or input error.

use std::ffi::OsString;
use std::io::Write;
use std::path::PathBuf;

use fineprint_dsl::vocab::RulesVocabulary;
use serde_json::Value;

use super::{GenError, generate};

/// The committed vocabulary, relative to the repository root.
pub const DEFAULT_OUT: &str = "crates/fineprint-dsl/data/vocab.json";

/// The usage text.
pub const USAGE: &str = "usage: fineprint-ingest vocab --cr <rules.txt> [--out <file>|-] [--check]";

struct Args {
    cr: PathBuf,
    out: OsString,
    check: bool,
}

fn parse_args(args: &[OsString]) -> Result<Args, String> {
    let mut cr = None;
    let mut out = None;
    let mut check = false;
    let mut it = args.iter();
    while let Some(a) = it.next() {
        match a.to_str() {
            Some("--cr") => {
                let v = it.next().ok_or("--cr needs a path")?;
                if cr.replace(PathBuf::from(v)).is_some() {
                    return Err("--cr given twice".to_owned());
                }
            }
            Some("--out") => {
                let v = it.next().ok_or("--out needs a path")?;
                if out.replace(v.clone()).is_some() {
                    return Err("--out given twice".to_owned());
                }
            }
            Some("--check") => check = true,
            _ => return Err(format!("unexpected argument {}", a.to_string_lossy())),
        }
    }
    let cr = cr.ok_or("--cr <rules.txt> is required")?;
    let out = out.unwrap_or_else(|| OsString::from(DEFAULT_OUT));
    if check && out == "-" {
        return Err("--check compares with a file; --out - is not allowed".to_owned());
    }
    Ok(Args { cr, out, check })
}

/// Runs the `vocab` subcommand; returns the exit code.
pub fn run(args: &[OsString], stdout: &mut dyn Write, stderr: &mut dyn Write) -> i32 {
    let args = match parse_args(args) {
        Ok(a) => a,
        Err(m) => {
            let _ = writeln!(stderr, "vocab: {m}\n{USAGE}");
            return 2;
        }
    };
    let cr = match std::fs::read(&args.cr) {
        Ok(b) => b,
        Err(e) => {
            let _ = writeln!(stderr, "vocab: cannot read --cr {}: {e}", args.cr.display());
            return 2;
        }
    };
    let vocab = match generate(&cr) {
        Ok(v) => v,
        Err(e) => return fail(stderr, &e),
    };
    let bytes = match vocab.to_canonical_bytes() {
        Ok(b) => b,
        Err(e) => {
            let _ = writeln!(stderr, "vocab: {e}");
            return 2;
        }
    };
    let summary = summary(&vocab);
    let out_path = PathBuf::from(&args.out);
    if args.check {
        return check(&out_path, &bytes, &vocab, &summary, stdout, stderr);
    }
    if args.out == "-" {
        if stdout.write_all(&bytes).is_err() {
            return 2;
        }
        let _ = writeln!(stderr, "vocab: wrote stdout ({summary})");
        return 0;
    }
    if let Err(e) = std::fs::write(&out_path, &bytes) {
        let _ = writeln!(
            stderr,
            "vocab: cannot write --out {}: {e}",
            out_path.display()
        );
        return 2;
    }
    let _ = writeln!(stdout, "vocab: wrote {} ({summary})", out_path.display());
    0
}

fn fail(stderr: &mut dyn Write, e: &GenError) -> i32 {
    let _ = writeln!(stderr, "vocab: {e}");
    e.exit_code()
}

fn summary(v: &RulesVocabulary) -> String {
    format!(
        "{} card types, {} supertypes, {} subtype groups, {} keyword abilities, \
         {} keyword actions, {} counter kinds, {} predefined tokens",
        v.card_types.len(),
        v.supertypes.len(),
        v.subtype_groups.len(),
        v.keyword_abilities.len(),
        v.keyword_actions.len(),
        v.counter_kinds.len(),
        v.predefined_tokens.len()
    )
}

fn check(
    path: &std::path::Path,
    bytes: &[u8],
    vocab: &RulesVocabulary,
    summary: &str,
    stdout: &mut dyn Write,
    stderr: &mut dyn Write,
) -> i32 {
    let committed = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) => {
            let _ = writeln!(
                stderr,
                "vocab: {} is missing or unreadable ({e}); regenerate it",
                path.display()
            );
            return 1;
        }
    };
    if committed == bytes {
        let _ = writeln!(
            stdout,
            "vocab: {} matches the CR ({summary})",
            path.display()
        );
        return 0;
    }
    let _ = writeln!(
        stderr,
        "vocab: {} differs from regeneration: {}; regenerate with \
         `cargo run --locked -p fineprint-ingest -- vocab --cr <rules.txt>`",
        path.display(),
        first_difference(&committed, vocab)
    );
    1
}

/// Names the first top-level member that differs (wire order), or why the file cannot be
/// compared member by member. Never contains CR text.
#[must_use]
pub fn first_difference(committed: &[u8], vocab: &RulesVocabulary) -> String {
    let loaded = match RulesVocabulary::from_slice(committed) {
        Ok(v) => v,
        Err(e) => return format!("the committed file does not load ({e})"),
    };
    let (Ok(Value::Object(a)), Ok(Value::Object(b))) =
        (serde_json::to_value(&loaded), serde_json::to_value(vocab))
    else {
        return "the vocabularies cannot be compared".to_owned();
    };
    const ORDER: [&str; 9] = [
        "vocabularyVersion",
        "crEffectiveDate",
        "cardTypes",
        "supertypes",
        "subtypeGroups",
        "keywordAbilities",
        "keywordActions",
        "counterKinds",
        "predefinedTokens",
    ];
    for key in ORDER {
        if a.get(key) != b.get(key) {
            return format!("first differing section `{key}`");
        }
    }
    "the content is equal but the bytes are not canonical".to_owned()
}
